<template>
  <div v-if="application" class="ordinary-detail">
    <div class="heading"><h3>{{ application.storageSubjectName || '未选择收储主体' }}</h3><el-tag>{{ labels[application.status] }}</el-tag></div><p>{{ application.id }}</p>
    <section><h4>申报用户与收储主体</h4><el-descriptions :column="2" border>
      <el-descriptions-item label="申报人">{{ application.applicant?.name }}</el-descriptions-item><el-descriptions-item label="申报单位">{{ application.applicant?.unit }}</el-descriptions-item><el-descriptions-item label="操作身份">{{ application.applicant?.roleName }}</el-descriptions-item><el-descriptions-item label="申报联系方式">{{ application.applicantContact }} · {{ application.applicantPhone }}</el-descriptions-item>
      <el-descriptions-item label="收储主体">{{ application.storageSubjectName }}</el-descriptions-item><el-descriptions-item label="主体类型">{{ STORAGE_SUBJECT_TYPES[application.storageSubject?.type] || '—' }}</el-descriptions-item><el-descriptions-item label="收储负责人">{{ application.storageSubject?.owner || '—' }}</el-descriptions-item><el-descriptions-item label="收储联系方式">{{ application.storageSubject?.phone || '—' }}</el-descriptions-item><el-descriptions-item label="收储主体地址" :span="2">{{ application.storageSubject?.address || '—' }}</el-descriptions-item>
    </el-descriptions></section>
    <section><h4>地块种植计划与收储计划</h4><div class="summary"><span>{{ application.year }}年 · {{ application.season }}</span><span>{{ application.plotDetails?.length || 0 }} 块地</span><span>申报面积 {{ format(application.area) }} 亩</span><span>预计产量 {{ format(application.expectedYield) }} 吨</span></div>
      <el-descriptions :column="2" border><el-descriptions-item label="计划实施时间">{{ application.implementationTime || '未填' }}</el-descriptions-item><el-descriptions-item label="收储用途">{{ application.usage === 'sell' ? '出售' : '自用' }}</el-descriptions-item><el-descriptions-item label="预计收储重量">{{ optional(application.weight) }}{{ application.weight != null ? ' 吨' : '' }}{{ application.weightIncomplete && application.weight != null ? '（已填部分合计）' : '' }}</el-descriptions-item><el-descriptions-item label="预计金额">{{ optional(application.expectedAmount) }}{{ application.expectedAmount != null ? ' 元（已填明细合计）' : '' }}</el-descriptions-item></el-descriptions>
      <el-table :data="application.plotDetails || []" border class="plot-table"><el-table-column prop="plotId" label="地块编号" width="115"/><el-table-column prop="name" label="地块名称" min-width="165"/><el-table-column prop="subjectName" label="种植主体" min-width="210"/><el-table-column label="作物" width="110"><template #default="{row}">{{ cropName(row.crop) }}</template></el-table-column><el-table-column prop="variety" label="品种" min-width="130"/><el-table-column label="面积（亩）" width="115"><template #default="{row}">{{ format(row.areaMu) }}</template></el-table-column><el-table-column label="地址/位置" min-width="150"><template #default="{row}">{{ row.location || row.name }}</template></el-table-column><el-table-column label="中心坐标" min-width="190"><template #default="{row}">{{ row.center?.map(value=>Number(value).toFixed(5)).join(', ') || '见地图边界' }}</template></el-table-column><el-table-column prop="expectedYield" label="预计产量（吨）" width="135"/><el-table-column label="预计价格（元/吨）" width="155"><template #default="{row}">{{ optional(row.expectedPrice) }}</template></el-table-column><el-table-column label="预计重量（吨）" width="135"><template #default="{row}">{{ optional(row.expectedWeight) }}</template></el-table-column></el-table>
      <div class="map-wrap"><BaseMap ref="mapRef" /></div><p class="muted">绿色范围为本单所选地块的精确边界。</p>
    </section>
    <section><h4>订单/合同与电子承诺书</h4><div class="files"><el-button v-for="(file,index) in application.attachments || []" :key="index" @click="previewFile(file)">{{ typeof file === 'string' ? file : file.name }} · 查看</el-button></div><p v-if="!application.attachments?.length" class="muted">{{ application.usage === 'self' ? '自用，无出售合同附件' : '未上传订单/合同' }}</p><div class="promise"><p>{{ application.promise?.content || '未填写承诺书' }}</p><small>版本：{{ application.promise?.version || '—' }}　签署人：{{ application.promise?.signer || '未签署' }}　时间：{{ application.promise?.signedAt || '未签署' }}</small></div></section>
    <section><h4>审核与备案</h4><el-descriptions :column="2" border><el-descriptions-item label="提交时间">{{ application.submittedAt || '未提交' }}</el-descriptions-item><el-descriptions-item label="审核截止">{{ ordinaryDeadline(application) || '未开始计时' }}</el-descriptions-item><el-descriptions-item label="备案编号" :span="2">{{ application.filedNo || '未备案' }}</el-descriptions-item></el-descriptions><el-timeline class="trail"><el-timeline-item v-for="(event,index) in application.auditTrail || []" :key="index" :timestamp="event.time"><b>{{ event.action }}</b> · {{ event.user }}<p v-if="event.opinion">{{ event.opinion }}</p></el-timeline-item></el-timeline><div v-if="application.status === 'filed'" class="result-links"><el-button @click="router.push({path: '/sil/fence', query: {id: application.id}})">查看精确围栏</el-button><el-button @click="router.push({path: '/onemap/silage', query: {id: application.id}})">查看青贮一张图</el-button><el-button @click="router.push({path: '/sil/ledger', query: {id: application.id}})">查看收储台账</el-button></div></section>
    <el-dialog v-model="previewVisible" title="附件查看" width="min(900px, 94vw)" append-to-body destroy-on-close><p>{{ preview?.name }}</p><img v-if="preview?.url && preview.type?.startsWith('image/')" :src="preview.url" alt="订单或合同附件" class="attachment-image"/><iframe v-else-if="preview?.url && (preview.type === 'application/pdf' || preview.name?.toLowerCase().endsWith('.pdf'))" :src="preview.url" title="附件预览" class="attachment-frame"/><a v-else-if="preview?.url" :href="preview.url" :download="preview.name">下载查看附件</a><el-empty v-else description="此示例仅有文件名；请在申报页选择本地附件以演示预览"/></el-dialog>
  </div><el-empty v-else description="申报不存在或当前身份无权查看"/>
</template>
<script setup>
import { nextTick, onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import BaseMap from '@/components/map/BaseMap.vue'
import { STORAGE_SUBJECT_TYPES, ordinaryDeadline } from '@/api/silOrdinary'
import { readSilCropDict } from '@/mock/sil/crops'
const props = defineProps({ application: { type: Object, default: null } })
const labels = { draft: '草稿', pending: '待审核', returned: '退回补正', rejected: '已驳回', filed: '已备案' }
const router = useRouter(); const mapRef = ref(null); const previewVisible = ref(false); const preview = ref(null)
const format = value => Number(value || 0).toFixed(1)
const optional = value => value === null || value === undefined || value === '' ? '未填' : Number(value).toLocaleString('zh-CN', { maximumFractionDigits: 2 })
const cropName = code => readSilCropDict().find(row => row.code === code)?.name || code
const previewFile = file => { preview.value = typeof file === 'string' ? { name: file } : file; previewVisible.value = true }
const draw = async () => {
  await nextTick(); if (!mapRef.value) return
  const features = (props.application?.plotDetails || []).filter(plot => plot.geometry).map(plot => ({ type: 'Feature', properties: { id: plot.plotId, name: plot.name }, geometry: plot.geometry }))
  const layer = mapRef.value.addGeoJSON('ordinary-detail', { type: 'FeatureCollection', features }, { style: { color: '#21876b', weight: 2, fillOpacity: 0.25 }, onEachFeature: (feature, polygon) => polygon.bindTooltip(document.createTextNode(feature.properties.name)) })
  if (features.length && layer?.getBounds().isValid()) mapRef.value.fitBounds(layer.getBounds())
}
watch(() => props.application, draw, { deep: true }); onMounted(draw)
</script>
<style scoped>
.ordinary-detail{min-width:0;color:#344054;overflow-wrap:anywhere}.heading{display:flex;justify-content:space-between;gap:16px}.heading h3{margin:0;font-size:19px}section{margin-top:22px}h4{margin:0 0 12px;border-left:3px solid #21876b;padding-left:10px}.summary{display:flex;gap:12px;flex-wrap:wrap;background:#f1f8f5;padding:12px;margin-bottom:12px;border-radius:8px;font-size:13px}.plot-table{max-width:100%;margin-top:14px}.map-wrap{position:relative;height:260px;margin-top:14px;border-radius:8px;overflow:hidden}.muted{color:#667085;font-size:12px}.files{display:flex;flex-wrap:wrap;gap:8px}.files :deep(.el-button){margin:0;max-width:100%;white-space:normal;height:auto;min-height:32px}.promise{padding:14px;background:#f8fafb;border:1px solid #e4e7ec;border-radius:8px;margin-top:14px;white-space:pre-wrap}.promise small{color:#667085}.trail{margin-top:20px}.attachment-image{max-width:100%;display:block;margin:auto}.attachment-frame{width:100%;height:60vh;border:0}.ordinary-detail :deep(.el-descriptions__content){overflow-wrap:anywhere}@media(max-width:600px){.ordinary-detail :deep(.el-descriptions__table){table-layout:fixed}.ordinary-detail :deep(.el-descriptions__label){width:78px!important}.ordinary-detail :deep(.el-descriptions__cell){font-size:12px;padding:8px!important}.map-wrap{height:220px}}
.result-links{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}.result-links .el-button{margin:0}
</style>


